`timescale 1ns / 1ps
module fft_4(
	input				clk,
	input				rst,
	input				start4,
	input				end4,
	input	[32-1:0]	A_real,
	input	[32-1:0]	A_img,
	output	[32-1:0]	out_real4,
	output	[32-1:0]	out_img4,
	output				start2,
	output				end2
);

/*****************<-------Control Registers and state machine------->*********************/
	parameter	PERIOD				=	4;
	parameter	HALT_FOR_NEXT_LAYER		=	6 + (PERIOD)/2;
	parameter	STATE_IDLE			=	3'd0;
	parameter	STATE_START			=	3'd1;
	parameter	STATE_PROCESSING	=	3'd2;
	parameter	STATE_END			=	3'd3;
	reg	[2:0]	r_state4			=	0;
	reg			butterfly_enable	=	0;
	reg			S4				= 0;
	reg	[1:0]	S4_counter		= 1;
	reg	[4:0]	start2_counter		= 0;


	always@(posedge clk) begin
		if(rst == 1)begin
			r_state4	<=	STATE_IDLE;
		end else begin
			case(r_state4)
				STATE_IDLE:begin
					if(start4 == 1)begin
						r_state4	<=	STATE_START;
					end else begin
						r_state4	<=	r_state4;
					end
				end
				STATE_START:begin
					r_state4	<=	STATE_PROCESSING;
				end
				STATE_PROCESSING:begin
					if(end4 == 1)begin
						r_state4	<=	STATE_END;
					end else begin
						r_state4	<=	r_state4;
					end
				end
				STATE_END:begin
					r_state4	<=	STATE_IDLE;
				end
				default:r_state4 = STATE_IDLE;
			endcase
		end
	end

/*****************<-------butterfly control------>*********************/

	always@(posedge clk) begin
		if(rst == 1)begin
			butterfly_enable	<=	0;
		end else begin
			if(r_state4 == STATE_START | r_state4 == STATE_PROCESSING | start4 == 1) begin
				butterfly_enable	<=	1;
			end else if (r_state4== STATE_END) begin
				butterfly_enable	<=	0;
			end else begin
				butterfly_enable	<=	butterfly_enable;
			end
		end
	end

	always@(posedge clk) begin
		if(rst == 1)begin
			S4_counter	<=	0;
		end else begin
			if(r_state4 == STATE_START | r_state4 == STATE_PROCESSING) begin
				S4_counter	<=	S4_counter + 1;
			end else begin
				S4_counter	<=	S4_counter;
			end
		end
	end

