	reg		[32-1:0]	r_C_img;
	wire	[32-1:0]	w_C_real;
	wire	[32-1:0]	w_C_img;

/*****************<-------延时单元，简单，不用ram------->***************/

//第二级延时两个clk，减去加法运算消耗，只需要延�?1�?
	always@(posedge clk) begin
		if(rst == 1)begin
			r_C_real<= 0;
			r_C_img	<= 0;
