/*****************<-------Rotators------->*********************/
	reg					counter;
	reg		[18-1:0]	r_rorator_real;
	reg		[18-1:0]	r_rorator_img;
	/**real	: 1 1 1 0*/
	/**img	: 0 0 0 -1*/
	/**rotator left shift 16 bits to finish fix-point calculation*/
	always@(posedge clk) begin
		if(rst == 1)begin
			r_rorator_real	<=	1<<16;
			//r_rorator_real	<=	1;
			r_rorator_img	<=	0;
		end else begin
			if(counter == 1) begin
				r_rorator_real	<=	0;
