	.C_real			(	w_C_real),
	.C_img			(	w_C_img),
	.B_real			(	w_B_real),
	.B_img			(	w_B_img),
	.D_real			(	w_D_real_tmp),
	.D_img			(	w_D_img_tmp)
 );

multiplier multiplier(
	.a				(	w_D_real_tmp),
	.b				(	w_D_img_tmp),
	.c				(	r_rorator_real),
	.d				(	r_rorator_img),
	.clk			(	clk),
	.rstn			(	~rst),
	.data_real		(	),
	.data_img		(	),
	.data_real_trunc(	w_out_real4),
	.data_img_trunc	(	w_out_img4)
);

endmodule

