			r_data_real_trunc	<=	0;
			r_data_img_trunc	<=	0;
		end else begin
			r_data_real_trunc	<= r_data_real_shifted[31:0];
			r_data_img_trunc	<= r_data_img_shifted[31:0];
		end
	end


	mult2 real_bd(
	.CLK		(clk	), 
